import jakarta.validation.constraints.NotBlank;

/**
 * 封锁登记时对单个受影响已发布计划的处理指令。
 * action 为 CANCEL 时撤销该计划；为 RESCHEDULE 时整单改签为 newScheduleKey 指向的同运营日草稿。
 *
 * @param scheduleKey    受影响的已发布计划业务键
 * @param action         处理动作：CANCEL / RESCHEDULE
 * @param newScheduleKey 改签后继草稿业务键；action=RESCHEDULE 时必填，CANCEL 时必须为空
 */
public record WorkBlockPlanAction(
        @NotBlank String scheduleKey,
        @NotBlank String action,
        String newScheduleKey) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.Instant;
import java.util.List;

/**
 * 区段维护封锁登记请求。窗口按 UTC 左闭右开比较，相邻端点不算冲突。
 * plans 必须列出登记时刻所有与窗口相交的已发布计划，并在同一事务内全部撤销或改签；
 * 遗漏任一相交计划则整单 422 回滚，封锁不生效。无相交计划时传空列表。
 */
public record RegisterWorkBlockRequest(
        @NotBlank String requestKey,
        @NotBlank String blockKey,
        @NotBlank String sectionId,
        @NotNull Instant startUtc,
        @NotNull Instant endUtc,
        @NotNull @Size(max = 30) List<@Valid WorkBlockPlanAction> plans) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 批量改签中的单项：将已发布旧计划原子改签为同运营日的新草稿。
 * 两个期望版本分别对旧、新计划做乐观校验。
 */
public record BatchRescheduleItem(
        @NotBlank String oldScheduleKey,
        @NotBlank String newScheduleKey,
        @NotNull Integer expectedOldVersion,
        @NotNull Integer expectedNewVersion) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;

/**
 * 批量原子改签请求：同一事务内按顺序完成全部单项改签，
 * 任一项状态、版本、关联或时隙（含区段封锁）校验失败则整体回滚，
 * 全部计划与封锁状态保持原样。requestKey 为幂等键。
 */
public record BatchRescheduleRequest(
        @NotBlank String requestKey,
        @NotNull @Size(min = 1, max = 30) List<@Valid BatchRescheduleItem> plans) {
}

package com.example.starter.plan.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 受影响计划处理结果视图：登记时的原计划键、处理结果、改签后继键（撤销时为 null）
 * 及与封锁相交的原占用快照（原区段、原时段，不受后续改签影响）。
 */
public record AffectedPlanView(String scheduleKey, String action, String successorScheduleKey,
                               List<OccupancyView> slots) {
}

package com.example.starter.plan.web.dto;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

/**
 * 封锁详情视图：封锁窗口本身（UTC 左闭右开）与登记时受影响计划的处理结果。
 */
public record WorkBlockResponse(String blockKey, String sectionId, LocalDate opDate,
                                Instant startUtc, Instant endUtc, String status,
                                List<AffectedPlanView> affectedPlans) {
}

package com.example.starter.plan.web.dto;

import java.util.List;

/**
 * 批量原子改签响应：与请求顺序一致的各项改签结果（旧计划已取消、新计划已发布）。
 * 任一项失败时整体回滚，不会返回本响应。
 */
public record BatchRescheduleResponse(List<RescheduleResponse> results) {
}

